'use strict';
const archiveState={data:null,error:null,query:'',page:1};
async function loadPublisherInventory(audit){const ref=audit.publisher_video_inventory;if(!ref)return;try{if(ref.file!=='publisher-video-index.json')throw Error('Unexpected publisher inventory path.');const response=await fetch(ref.file);if(!response.ok)throw Error('Publisher inventory returned HTTP '+response.status);const d=await response.json();if(d.schema_version!==1||!Array.isArray(d.videos)||d.synthetic_fixture_run===true)throw Error('Invalid publisher inventory.');archiveState.data=d;archiveState.error=null;}catch(e){archiveState.error=e.message;archiveState.data=null;}}
function archiveRows(){const q=archiveState.query.trim().toLowerCase();return arr(archiveState.data?.videos).filter(v=>!q||[v.video_id,...arr(v.publisher_link_labels)].join(' ').toLowerCase().includes(q));}
function archiveTable(){const rows=archiveRows(),pages=Math.max(1,Math.ceil(rows.length/20));archiveState.page=Math.min(archiveState.page,pages);return `<div class="result-summary archive-result-summary"><p><strong>${rows.length}</strong> publisher-linked video IDs match. Titles are publisher link labels; uploader identity and durations have not been reverified on YouTube.</p><button type="button" id="export-archive" class="secondary">Export filtered publisher links</button></div><div class="table-wrap" role="region" tabindex="0" aria-label="Publisher-linked video discovery inventory"><table class="source-table"><thead><tr><th scope="col">Publisher link label / video ID</th><th scope="col">Discovery page</th><th scope="col">Duration</th><th scope="col">Media acquired in this crawl</th></tr></thead><tbody>${rows.slice((archiveState.page-1)*20,archiveState.page*20).map(v=>`<tr><th scope="row">${link(v.url,arr(v.publisher_link_labels)[0]||v.video_id)}<small>${esc(v.video_id)}</small></th><td>${arr(v.publisher_page_urls).map(url=>link(url,'Publisher archive page')).join('<br>')}</td><td>${number(v.duration_seconds)}</td><td>${v.downloaded_from_youtube===false?'Not downloaded':v.downloaded_from_youtube===true?'Downloaded':'Unknown'}</td></tr>`).join('')||'<tr><td colspan="4">No publisher-linked IDs match this search.</td></tr>'}</tbody></table></div><div class="pager archive-pager"><button type="button" class="secondary" data-archive-page="${archiveState.page-1}" ${archiveState.page<=1?'disabled':''}>Previous</button><span>Page ${archiveState.page} of ${pages}</span><button type="button" class="secondary" data-archive-page="${archiveState.page+1}" ${archiveState.page>=pages?'disabled':''}>Next</button></div>`;}
function publisherVideoView(){const d=archiveState.data;if(!d)return archiveState.error?`<section id="publisher-video-inventory" class="section"><h2>Publisher-linked video discovery</h2><p class="empty">${esc(archiveState.error)}</p></section>`:'';const c=d.counts||{};return `<section id="publisher-video-inventory" class="section" tabindex="-1"><div class="section-head"><h2>A larger discovery frame.</h2><p>${esc(d.publisher)}’s own archive pages expose a separate set of YouTube links. These are newly indexed source links, kept distinct from the historical account-route index above.</p></div><div class="discovery-strip"><div><b>${number(c.unique_youtube_ids_linked)}</b><span>distinct publisher-linked YouTube IDs</span></div><div><b>${number(c.archive_pages_retrieved)}</b><span>publisher archive pages retrieved</span></div><div><b>${number(c.youtube_media_downloaded_this_crawl)}</b><span>YouTube media acquired in this crawl</span></div><div><b>${number(c.youtube_uploads_total)}</b><span>total YouTube channel uploads</span></div></div><div class="scope-note"><p><strong>Discovery is not collection.</strong> These URLs establish a possible collection frame from the publisher’s archive, not a complete channel census, a duration audit or retained media. No minimum duration applies to this non-Bashar source.</p><p>${esc(d.method)}</p></div><div class="toolbar"><label class="search-label">Search publisher link labels and IDs<input type="search" id="archive-query" value="${esc(archiveState.query)}" placeholder="Video ID, title word or publisher label"></label><button type="button" id="clear-archive" class="secondary">Clear archive search</button></div><div id="archive-results">${archiveTable()}</div><details><summary>Publisher-archive method and limitations</summary><ul class="limits">${arr(d.limitations).map(l=>`<li>${esc(typeof l==='string'?l:JSON.stringify(l))}</li>`).join('')}</ul></details><div class="download-list"><a href="publisher-video-index.json" download>Download complete publisher video index JSON</a>${link(d.seed_url,'Open publisher archive')}</div></section>`;}
function updateArchive(){document.querySelector('#archive-results').innerHTML=archiveTable();announce(archiveRows().length+' publisher-linked video IDs match.');}
app.addEventListener('input',e=>{if(e.target.id==='archive-query'){archiveState.query=e.target.value;archiveState.page=1;updateArchive();}});
app.addEventListener('click',e=>{if(e.target.id==='clear-archive'){archiveState.query='';archiveState.page=1;document.querySelector('#archive-query').value='';updateArchive();document.querySelector('#archive-query').focus();}const b=e.target.closest('[data-archive-page]');if(b&&!b.disabled){archiveState.page=Number(b.dataset.archivePage);updateArchive();(app.querySelector('.archive-pager button:last-child:not(:disabled)')||app.querySelector('.archive-pager button:first-child:not(:disabled)'))?.focus();}if(e.target.id==='export-archive'){const headers=['video_id','url','publisher_link_labels','publisher_page_urls','duration_seconds','youtube_uploader_reverified','downloaded_from_youtube'],rows=archiveRows(),body=[headers,...rows.map(v=>headers.map(k=>Array.isArray(v[k])?v[k].join('; '):v[k]))].map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n',url=URL.createObjectURL(new Blob([body],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='publisher-linked-video-index.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Exported '+rows.length+' publisher-linked video IDs.');}});
